@@ -0,0 +1,63 @@
+import { Redis } from "ioredis"
+import { createRedisClient } from "../config/redis.js"
+
+export type ActivityType = "step_start" | "step_done" | "phase" | "note"
+
+export type ActivityEntry = {
+  id: string
+  ts: string
+  type: ActivityType
+  stepId?: number | undefined
+  phase?: string | undefined
+  message: string
+  meta?: Record<string, unknown> | undefined
+}
+
+export class ActivityStore {
+  private redis: Redis
+  private TTL = 60 * 60 * 24 * 7 // 7 days
+
+  constructor() {
+    this.redis = createRedisClient()
+  }
+
+  private key(taskId: string) {
+    return `activity:${taskId}`
+  }
+
+  async append(taskId: string, entry: Omit<ActivityEntry, 'id' | 'ts'> & Partial<Pick<ActivityEntry, 'id' | 'ts'>>) {
+    const now = new Date().toISOString()
+    const id = entry.id ?? (typeof crypto !== 'undefined' && (crypto as any).randomUUID ? (crypto as any).randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2,8)}`)
+    const full: ActivityEntry = {
+      id,
+      ts: entry.ts ?? now,
+      type: entry.type,
+      stepId: entry.stepId,
+      phase: entry.phase,
+      message: entry.message,
+      meta: entry.meta,
+    }
+    const key = this.key(taskId)
+    // LPUSH then trim to 100
+    await this.redis.lpush(key, JSON.stringify(full))
+    await this.redis.ltrim(key, 0, 99)
+    await this.redis.expire(key, this.TTL)
+    return full
+  }
+
+  async list(taskId: string, limit = 50): Promise<ActivityEntry[]> {
+    const key = this.key(taskId)
+    const end = Math.max(0, limit - 1)
+    const items = await this.redis.lrange(key, 0, end)
+    try {
+      return items.map((s) => JSON.parse(s) as ActivityEntry)
+    } catch {
+      return []
+    }
+  }
+
+  async clear(taskId: string): Promise<void> {
+    const key = this.key(taskId)
+    await this.redis.del(key)
+  }
+}
